ee:message.ee:set-payload:
%dw 2.0
output application/xml skipNullOn="everywhere"
ns soap http://www.w3.org/2003/05/soap-envelope
ns mdm http://www.etb.com.co/Gateway/MDM_Data_Services
---
{
	soap#Envelope: {
        soap#Header: {},
        soap#Body: {
            mdm#Get_PQR: {
                mdm#WSRequestHeader: {
                    mdm#system: {
                        mdm#name: "MDM_Data_Services",
                        mdm#correlationId: attributes.headers.'X-CORRELATION-ID',
                        mdm#processingServer: "MULESOFT"
                    }
                },
                mdm#WSRequestBody: {
                    mdm#id: payload.id,
                    mdm#PQR_number: payload.pqrNumber,
                    mdm#customer_document_type: payload.customerDocumentType,
                    mdm#customer_document_number: payload.customerDocumentNumber,
                    mdm#connection_number: payload.connectionNumber,
                    mdm#billing_account: payload.billingAccount,
                    mdm#cun: payload.cun,
                    mdm#assigned_user: payload.assignedUser,
                    mdm#tipo_consulta: payload.tipoConsulta,
                    mdm#tipo_servicio: payload.tipoServicio,
                    mdm#canal_recepcion: payload.canalRecepcion,
                    mdm#dias_habiles: payload.diasHabiles,
                    mdm#estado: payload.estado
                }
            }
        }
    }
}

%dw 2.0 output application/json --- { "status": 200, "code": "OK", "response": { "get_pqrResponse": { "get_pqrResult": { "wsResponseHeader": { "system": { "name": payload.Envelope.Body.Get_PQRResponse.Get_PQRResult.WSResponseHeader.system.name, "correlationId": payload.Envelope.Body.Get_PQRResponse.Get_PQRResult.WSResponseHeader.system.correlationId, "processingServer": payload.Envelope.Body.Get_PQRResponse.Get_PQRResult.WSResponseHeader.system.processingServer }, "service": { "status": payload.Envelope.Body.Get_PQRResponse.Get_PQRResult.WSResponseHeader.service.status, "responseDate": payload.Envelope.Body.Get_PQRResponse.Get_PQRResult.WSResponseHeader.service.responseDate, "statusDetail": payload.Envelope.Body.Get_PQRResponse.Get_PQRResult.WSResponseHeader.service.statusDetail }, "property": payload.Envelope.Body.Get_PQRResponse.Get_PQRResult.WSResponseHeader.property
}, "wsResponseBody": payload.Envelope.Body.Get_PQRResponse.Get_PQRResult.WSResponseBody.*PQR_PQR map (obj,ind) -> { "pqrPQR": { "extract_update": obj.actualizacion_extractor, "id": obj.Id, "rowIdPQR": obj.row_id_pqr, "pqrNumber": obj.numero_pqr, "documentType": obj.tipo_documento, "identificationNumber": obj.numero_identificacion, "contactDocumentType": obj.contacto_tipo_documento, "contactDocumentNumber": obj.contacto_numero_documento, "serviceId": obj.id_servicio, "connectionNumber": obj.numero_conexion, "serviceAccount": obj.cuenta_servicio, "billingAccount": obj.cuenta_facturacion, "product": obj.producto, "orderNumber": obj.numnumero_pedido, "pqrComplaintPQR": obj.pqr_reclamo_pqr, "typePqrComplaint": obj.tipo_pqr_reclamo, "cun": obj.cun, "service": obj.servicio, "technology": obj.tecnologia, "pqrType": obj.tipo_pqr, "pqrClass": obj.clase_pqr, "pqrMotive": obj.motivo_pqr, "pqrCausal": obj.causal_pqr, "pqrUrgency": obj.urgencia_pqr, "impact": obj.impacto, "pqrSymptom": obj.sintoma_pqr, "claimedValue": obj.valor_reclamado, "adjustedValue": obj.valor_ajustado, "creationDate": obj.fecha_creacion, "radication_Date": obj.fecha_radicacion, "solutionDate": obj.fecha_solucion, "solution": obj.solucion, "accountability": obj.imputabilidad, "pqrStatus": obj.estado_pqr, "remedySendingState": obj.estado_envio_remedy, "closingType": obj.Tipo_cierre, "pqrNotificationVia": obj.medio_notificacion_pqr, "receptionVia": obj.medio_recepcion, "pqrDescription": obj.descripcion_pqr, "pqrResponse": obj.respuesta_pqr, "numIncidenceRemedy": obj.num_incidendia_remedy, "responseRemedy": obj.respuesta_remedy, "systemOriginId": obj.id_sistema_origen, "systemOrigin": obj.sistema_origen, "lspCallSource": obj.lsp_origen_llamada, "lspThirdDestination": obj.lsp_tercer_destino, "pqrFullFlag": obj.indicador_pqr_completa, "email": obj.correo_electronico, "cunMassiveFailure": obj.cun_falla_masiva, "writtenNotificationAddress": obj.direccion_notificacion_escrita, "externalRooted": obj.radicado_externo, "flagAppealResource": obj.flag_recurso_apelacion, "flagTransferGovernment": obj.flag_traslado_gobierno, "flagRecurringCustomer": obj.flag_cliente_recurrente, "flagReopening": obj.flag_reapertura, "priority": obj.prioridad, "creatorUser": obj.usuario_creador, "assignedUser": obj.usuario_asignado, "comments": obj.comentarios, "customerName": obj.nombre_cliente, "customerSegment": obj.segmento_cliente, "resolutionCode": obj.codigo_resolucion, "resolurionDescription": obj.descripcion_resolucion, "subChannel": obj.subcanal, "point": obj.punto, "supplier": obj.proveedor, "management": obj.gerencia, "stoplight": obj.semaforo, "businessDays": obj.dias_habiles, "waitStartDate": obj.Fecha_Inicio_Espera, "waitEndDate": obj.Fecha_Fin_Espera, "cunRelated": obj.cun_relacionado, "contactName": obj.nombre_contacto, "receptionChannel": obj.canal_recepcion, },
"pqrExtensions": obj.pqr_extensiones.*PQR_EXTENSION map (o,i) -> { "pqrExtension": { "extensionDays": o.dias_extension, "extensionStartDate": o.fecha_incio_extension, "extensionEndDate": o.fecha_fin_extension } }, "pqrActivitiesPQR": obj.pqr_actividades_pqr.*PQR_ACTIVIDAD_PQR map (o, i) -> { "pqrActivityPQR": { "extractorUpdate": o.actualizacion_extractor, "activityRowId": o.row_id_actividad, "activityName": o.nombre_actividad, "activityStatus": o.estado_actividad, "comments": o.comentarios, "description": o.descripcion, "management": o.gestion, "managementDescription": o.descripcion_gestion, "activityGroup": o.grupo_actividad, "assignedUser": o.usuario_asignado, "userCreatorActivity": o.usuario_creador_actividad, "activityStartDate": o.fecha_inicio_actividad, "currentStatusDate": o.fecha_estado_actual, "activityDueDate": o.fecha_vencimiento_actividad, "final": o.final, "priority": o.prioridad, "disconnectionDate": o.fecha_desconexion, "reconnectionDate": o.fecha_reconexion, "duration": o.duracion, "bill": o.cuenta, "notification": o.notificacion, "stoplight": o.semaforo, "businessDays": o.dias_habiles, "attachedActivities": o.actividades_adjuntas.*PQR_ADJUNTOS_ACTIVIDAD map (o1, i1) -> { "pqrAttachmentsActivity": { "attached_activities": o1.adjuntos_actividades } } } }, "pqrAttachedFiles": obj.pqr_archivos_adjuntos.*PQR_ARCHIVO_ADJUNTO map (o, i) -> { "pqrAttachedFile": { "attachedFile": o.archivo_adjunto } }, "characteristicsPQR": obj.Caracteristicas_pqr.*Caracteristicas_pqr map (o, i) -> { "characteristicsPQR": { "flowId": o.id_flujo, "url": o.url, "date": o.fecha } }, "pqrCharacteristics": obj.pqr_caracteristicas.*PQR_CARACTERISTICA map (o, i) -> { "pqrCharacteristics": { "characteristic": o.Caracteristica, "value": o.Valor } }, "pqrSuspensionDetail": obj.pqr_detalle_suspension.*PQR_DETALLE_SUSPENSION map (o, i) -> { "pqrSuspensionDetail": { "newGroup": o.nuevo_grupo, "suspensionStatus": o.estado_suspension, "causalReasonSupension": o.causal_motivo_supension, "groupChangeDate": o.fecha_cambio_grupo } }, "pqrVersion": obj.version_pqr, "flagNotificacion": obj.flag_notificacion, "earlyFailureFlag": obj.flag_fallaJoven, "secondLevelStatus": obj.Estado_Segundo_Nivel.*Estado_Segundo_Nivel map (o, i) -> { "secondLevelStatus": { "id": o.id, "code": o.Codigo, "description": o.Descripcion, "date": o.Fecha, "retries": o.Reintentos, "exceptionCode": o.CodigoExcepcion } }, "modificationDate": obj.fecha_modificacion, "subStatus": obj.sub_estado, "exception": obj.excepcion, "excepcionType": obj.tipo_excepcion, "originatedBy": obj.originada_por, "family": obj.familia, "contactType": obj.tipoContacto, "firm": obj.firma, "isMultiDetail": obj.EsMultidetalle, "contingentDate": obj.fecha_contingente, "shippingCommunications": { "communicationVia": obj.EnvioComunicaciones.MedioComunicacion, "communicationData1": obj.EnvioComunicaciones.DatoComunicacion1, "communicationData2": obj.EnvioComunicaciones.DatoComunicacion2 }, "mdmRelates": obj.mdm_relaciona, "annulmentMotive": obj.motivo_anulacion } } } } }
